import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { performance } from 'node:perf_hooks';
import { createDedicatedOrgPg } from './libs/papercusp/libs/db/src/connection.ts';
import { pairedBootstrapCI } from './libs/generic/bench-metrics/src/intervals.ts';
const inputs = {"queries":{"control":"SELECT feature_id, item_kind, harness_slug, title, summary, status, taken_by, taken_at, last_progress_at, parent_id, NULL::jsonb AS payload, needs_design, design_status, design_spec_id, discarded_design_work, assignee_rank, rank_writer, rank_updated_at, feature_order, created_ts, updated_ts, origin, audit_verdict, verified_author_github_user_id, terminal_owner, terminal_completion_ref, authority, closed_ts, goal_id, tags, source_plan_slug, source_plan_item_ids, redundancy, expected_cost_cents FROM harness_shared.harness_features_consolidated WHERE workspace_id='papercusp-workspace' AND harness_slug='papercusp' AND (parent_id IS NULL OR parent_id='') AND (item_kind='feature' OR item_kind IN (SELECT work_item_kind FROM harness_shared.datatype_registry WHERE workspace_id='papercusp-workspace' AND tier='generic-kind' AND status='active' AND work_item_kind IS NOT NULL)) ORDER BY updated_ts DESC NULLS LAST LIMIT 300","candidate":"SELECT feature_id, item_kind, harness_slug, title, summary, status, taken_by, taken_at, last_progress_at, parent_id, NULL::jsonb AS payload, needs_design, design_status, design_spec_id, discarded_design_work, assignee_rank, rank_writer, rank_updated_at, feature_order, created_ts, updated_ts, origin, audit_verdict, verified_author_github_user_id, terminal_owner, terminal_completion_ref, authority, closed_ts, goal_id, tags, source_plan_slug, source_plan_item_ids, redundancy, expected_cost_cents FROM harness_shared.harness_features_consolidated WHERE workspace_id='papercusp-workspace' AND harness_slug='papercusp' AND (parent_id IS NULL OR parent_id='') AND item_kind = ANY(ARRAY(SELECT 'feature'::text UNION SELECT work_item_kind FROM harness_shared.datatype_registry WHERE workspace_id='papercusp-workspace' AND tier='generic-kind' AND status='active' AND work_item_kind IS NOT NULL)) ORDER BY updated_ts DESC NULLS LAST LIMIT 300"},"queryHashes":{"control":"e0a56fb5dcac4c67448182bf24c68c3f097cc303151f9910a66dba3b335d6afb","candidate":"7164e9c80c414d73ade09c24b823d8f08d2381fa69f17692f8a77380d79626c9"},"sourceHashes":{"packages/operator-core/lib/work-items.ts":"e71c918817bc44b9f784f604d48494ebb0c75f3acd758ee5809784695b261969","packages/operator-core/lib/cache/cached-read.ts":"73b09e7f3c4b5a53511fd8c51d9cf81a4cc7eff6b2d21e774eeec049dbfc39c9","libs/papercusp/libs/db/src/connection.ts":"15ce7b0a0bd390fe46c80368621486758844841e7d1e6b00de5e08db2c21a5a0","libs/generic/bench-metrics/src/intervals.ts":"1875122463e2f06e8c2c0fe2423202ae957aaf12e7853b03cb03716ca74e32f2"},"head":"befef09f6b70432395b23f9eec017988882f597f"};
const sha = x => createHash('sha256').update(x).digest('hex');
const fingerprints = () => Object.fromEntries(Object.keys(inputs.sourceHashes).map(p => [p, sha(readFileSync(p))]));
const canonical = x => Array.isArray(x) ? x.map(canonical) : x && typeof x === 'object' ? Object.fromEntries(Object.entries(x).sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>[k,canonical(v)])) : typeof x === 'bigint' ? String(x) : x;
const digest = rows => sha(JSON.stringify(rows.map(r=>JSON.stringify(canonical(r))).sort()));
const result = {schemaVersion:'p008-query-client-wall-v1', manifestRef:'thread-post:1143257', startedAt:new Date().toISOString(), inputs, sourceBefore:fingerprints(), warmups:[], samples:[], failures:[]};
for(const [p,v] of Object.entries(inputs.sourceHashes)) if(result.sourceBefore[p]!==v) throw new Error('source fingerprint moved before run: '+p);
const {sql} = createDedicatedOrgPg('cache-p008-client-wall', {max:1});
try {
 await sql.begin('isolation level repeatable read read only', async tx => {
  await tx.unsafe("SET LOCAL statement_timeout = '15s'");
  const state = async () => (await tx.unsafe("SELECT txid_current_snapshot()::text AS snapshot, pg_backend_pid() AS backend_pid, current_setting('transaction_read_only') AS read_only, current_setting('transaction_isolation') AS isolation, current_setting('enable_seqscan') AS enable_seqscan, current_setting('enable_indexscan') AS enable_indexscan, current_setting('enable_bitmapscan') AS enable_bitmapscan, current_setting('plan_cache_mode') AS plan_cache_mode"))[0];
  result.before = await state();
  let expectedDigest;
  const sample = async (arm,pair,phase) => {
   const start=performance.now();
   try {
    const rows=await tx.unsafe(inputs.queries[arm],[],{prepare:false});
    const wallMs=performance.now()-start;
    const row={phase,pair,arm,wallMs,rowCount:rows.length,rowDigest:digest(rows)};
    (phase==='warmup'?result.warmups:result.samples).push(row);
    expectedDigest ??= row.rowDigest;
    if(row.rowCount!==300 || row.rowDigest!==expectedDigest) throw new Error('row equality/count failed for '+phase+'/'+pair+'/'+arm);
   } catch(e) {result.failures.push({phase,pair,arm,message:String(e),elapsedMs:performance.now()-start});throw e;}
  };
  for(const arm of ['control','candidate','candidate','control']) await sample(arm,null,'warmup');
  for(let pair=0;pair<6;pair++) for(const arm of pair%2===0?['control','candidate']:['candidate','control']) await sample(arm,pair,'measured');
  result.after = await state();
  result.plans={};
  for(const arm of ['control','candidate']) result.plans[arm]=(await tx.unsafe('EXPLAIN (FORMAT JSON) '+inputs.queries[arm],[],{prepare:false}))[0]['QUERY PLAN'];
 });
 if(result.before.snapshot!==result.after.snapshot || result.before.backend_pid!==result.after.backend_pid) throw new Error('snapshot/backend changed');
 const values=arm=>result.samples.filter(s=>s.arm===arm).sort((a,b)=>a.pair-b.pair).map(s=>s.wallMs);
 const median=a=>{const s=[...a].sort((a,b)=>a-b);return(s[2]+s[3])/2;};
 const a=values('control'),b=values('candidate');
 result.analysis={controlMedianMs:median(a),candidateMedianMs:median(b),pairedDeltasMs:b.map((v,i)=>v-a[i]),paired:pairedBootstrapCI(a,b,{ci:0.95,iterations:10000,seed:12345})};
 result.sourceAfter=fingerprints();
 result.sourceUnchanged=JSON.stringify(result.sourceBefore)===JSON.stringify(result.sourceAfter);
 result.status=result.sourceUnchanged?'complete':'source-moved';
} catch(e) {result.status='incomplete';result.error=String(e);process.exitCode=1;}
finally {await sql.end({timeout:5});result.finishedAt=new Date().toISOString();console.log(JSON.stringify(result));}
